def body(title, question, department, checks, version='1.0', status='active'):
    sections = [f'虚构企业 {title}\n\n{NOTICE}\n\n版本：{version}；状态：{status}；责任部门：{department}。',
                f'## 第一章 目的与适用范围\n\n本文件说明演示企业在“{question}”场景中的记录、核对和人工确认要求。适用范围为虚构DEMO企业的管理与复核活动，不是任何真实钢厂的工艺标准，也不定义设备操作参数。生产系统中的实际状态必须通过正式只读接口取得；规程文字不能证明某个炉次已经发生异常。不同钢种、工序和时间条件下，应另行取得相应有效规则。',
                '## 第二章 核对要求\n\n' + '\n\n'.join(checks)]
    for i, check in enumerate(checks, 1):
        sections.append(f'### 2.{i} 记录与执行边界\n\n{check}\n\n办理这项核对时，责任岗位应保留对象身份、发生时间、原始凭证、经核对的字段和人工确认情况。若资料来自多个系统，应逐项注明系统名称和实际来源版本，避免把名称相似的对象合并。对本项要求只能说明已经取得的事实；未取得字段应明确写为不可用，不能沿用另一炉次或另一订单的数据。确认结果应通过企业原有系统和授权流程留痕，网页上的辅助说明不能替代原始记录。')
    sections += [f'## 第三章 协同与升级\n\n{department}岗位负责本文件对应事项的人工复核；相关生产、质量、仓储和信息化人员按各自职责提供原始证据。发现对象关系不一致、来源版本冲突、单位无法对应或系统调用失败，应说明具体缺口并停止后续确定性结论。升级记录至少保留请求时间、涉及对象、来源系统、待确认事项和接收岗位，不包含密码、API密钥或Cookie。系统恢复以后重新取得有效数据，不能将失败前的未知状态直接改写成正常。',
                 '## 第四章 留痕、版本与AI边界\n\n本文件的正文、文档身份、版本与生效范围应一起维护。正文改变须重新登记hash并重新索引；不能只改标题或要求模型优先选最新版。历史、未来和撤销文件保留用于审计，不参与当前企业结论。两个有效版本同时适用而冲突时须由文控人员确认。AI回答需要给出本次真实片段出处；缺少直接支持、仅有类似措辞或没有足够适用条件时，应明确无法确认。人工确认始终保留，Copilot没有设备控制、库存扣减或订单修改权限。公开行业资料只能作一般参考，不能替代本文件的企业要求。']
    return '\n\n'.join(sections)


def document(code, title, question, department, checks, source_type='INTERNAL_CONTROLLED', version='1.0', status='active', start='2026-01-01', end='2030-01-01', content=None):
    text = content or body(title, question, department, checks, version, status)
    return {'chunk_id': code, 'source_file_name': code + '.md', 'document_name': '虚构企业' + title if source_type == 'INTERNAL_CONTROLLED' else title,
            'version': version, 'status': status, 'effective_date': start, 'effective_from': start + 'T00:00:00+00:00',
            'effective_until': end + 'T00:00:00+00:00', 'scope': 'FDEMO-ENTERPRISE' if source_type == 'INTERNAL_CONTROLLED' else 'PUBLIC-REFERENCE',
            'department': department, 'process_stage': 'management', 'steel_grade': 'DEMO-ALL', 'steel_grade_scope': 'DEMO-ALL',
            'rule_id': 'F-KNOWLEDGE-REVIEW', 'parameters': ['knowledge'], 'directions': ['reference'], 'chapter': '第二章',
            'section': '核对要求', 'page': None, 'content': text, 'checks': checks,
            'content_sha256': hashlib.sha256(text.encode()).hexdigest(), 'source_type': source_type, 'url': 'not-applicable', 'questions': [question]}


def main():
    folder = ROOT / 'assets/copilot_knowledge/documents'; folder.mkdir(parents=True, exist_ok=True)
    docs = [document(f'F-SOP-{i:02}-v1', *topic) for i, topic in enumerate(TOPICS, 1)]
    for label, version, status, start, end in [('retired', '0.9', 'expired', '2025-01-01', '2026-01-01'), ('future', '3.0', 'future', '2027-01-01', '2030-01-01'), ('revoked', '1.5', 'revoked', '2026-01-01', '2030-01-01')]:
        doc = copy.deepcopy(docs[5]);doc.update(chunk_id='F-SOP-06-' + label, source_file_name='F-SOP-06-' + label + '.md',
                                               version=version, status=status, effective_date=start, effective_from=start+'T00:00:00+00:00', effective_until=end+'T00:00:00+00:00')
        doc['content'] = body(TOPICS[5][0], TOPICS[5][1], TOPICS[5][2], TOPICS[5][3], version, status)
        doc['content_sha256'] = hashlib.sha256(doc['content'].encode()).hexdigest();docs.append(doc)
    for doc in docs:
        (folder / doc['source_file_name']).write_text(doc['content'], encoding='utf-8')
    corpus = {'source_type': 'INTERNAL_CONTROLLED', 'notice': NOTICE, 'documents': docs}
    (folder.parent / 'corpus.json').write_text(json.dumps(corpus, ensure_ascii=False, indent=2), encoding='utf-8')
    questions = [{'id': f'F-INTERNAL-{i:02}', 'question': topic[1], 'source_keys': [docs[i-1]['chunk_id']], 'expected': 'answered'} for i, topic in enumerate(TOPICS, 1)]
    questions += [{'id': 'F-CROSS-01', 'question': '生产和质量人员分别有哪些职责？', 'source_keys': [docs[23]['chunk_id'], docs[25]['chunk_id']], 'expected': 'answered'}]
    aliases = {6: ['温度偏差时规程要求检查什么？', '温度偏差时应该核对哪些记录？'],
               7: ['成分偏差时规程要求检查什么？'], 19: ['交接班需要核对什么？'],
               22: ['系统故障应该怎样上报？'], 29: ['现行规程对复核员有什么要求？']}
    for index, values in aliases.items():
        questions[index-1]['aliases'] = values
    (folder.parent / 'questions.json').write_text(json.dumps(questions, ensure_ascii=False, indent=2), encoding='utf-8')
    print('Original fictional controlled documents:', len(docs), 'current:', len(TOPICS), 'shortest characters:', min(len(d['content']) for d in docs))


if __name__ == '__main__':
    main()
